from pathlib import Path
path = Path('Zend/zend_generators.c')
src = path.read_text()

# Patch zend_generator_add_single_child
old = """static void zend_generator_add_single_child(zend_generator_node *node, zend_generator *child, zend_generator *leaf)
{
\tif (node->children == 0) {
\t\tnode->child.single.leaf = leaf;
\t\tnode->child.single.child = child;
\t} else {
\t\tif (node->children == 1) {
\t\t\tHashTable *ht = emalloc(sizeof(HashTable));
\t\t\tzend_hash_init(ht, 0, NULL, NULL, 0);
\t\t\tzend_hash_index_add_ptr(ht,
\t\t\t\t(zend_ulong) node->child.single.leaf, node->child.single.child);
\t\t\tnode->child.ht = ht;
\t\t}

\t\tif (zend_hash_index_add_ptr(node->child.ht, (zend_ulong) leaf, child) == NULL) {
\t\t\tZEND_ASSERT(node->children > 1);
\t\t\treturn;
\t\t}
\t}

\t++node->children;
}
"""
new = """static void zend_generator_add_single_child(zend_generator_node *node, zend_generator *child, zend_generator *leaf)
{
\tif (node->children == 0) {
\t\tnode->child.single.leaf = leaf;
\t\tnode->child.single.child = child;
\t\t/* The yield-from tree stores raw zend_generator* pointers. Keep the referenced
\t\t * generator alive while it is reachable through this node. */
\t\tGC_ADDREF(&child->std);
\t} else {
\t\tif (node->children == 1) {
\t\t\tHashTable *ht = emalloc(sizeof(HashTable));
\t\t\tzend_hash_init(ht, 0, NULL, NULL, 0);
\t\t\tzend_hash_index_add_ptr(ht,
\t\t\t\t(zend_ulong) node->child.single.leaf, node->child.single.child);
\t\t\tnode->child.ht = ht;
\t\t}

\t\t/* Each leaf->child entry owns a reference to the child generator. */
\t\tGC_ADDREF(&child->std);
\t\tif (zend_hash_index_add_ptr(node->child.ht, (zend_ulong) leaf, child) == NULL) {
\t\t\tZEND_ASSERT(node->children > 1);
\t\t\tOBJ_RELEASE(&child->std);
\t\t\treturn;
\t\t}
\t}

\t++node->children;
}
"""
if old not in src:
    raise SystemExit('Pattern for zend_generator_add_single_child not found')
src = src.replace(old, new)

# Patch zend_generator_remove_leaf_child
old = """static void zend_generator_remove_leaf_child(zend_generator_node *node, zend_generator *leaf, zend_generator *replace_leaf) {
\tif (node->children > 1) {
\t\tHashTable *ht = node->child.ht;
\tzend_ulong child_leaf;
\tzend_generator *child_generator;
\tzend_hash_index_del(ht, (zend_ulong) leaf);
\t\tif (--node->children == 1) {
\t\t\tZEND_HASH_FOREACH_NUM_KEY_PTR(ht, child_leaf, child_generator) {
\t\t\t\tnode->child.single.leaf = (zend_generator *) child_leaf;
\t\t\t\tnode->child.single.child = child_generator;
\t\t\t\tif (node->ptr.leaf == leaf) {
\t\t\t\t\tnode->ptr.leaf = (zend_generator *) child_leaf;
\t\t\t\t}
\t\t\t\tbreak;
\t\t\t} ZEND_HASH_FOREACH_END();
\t\t\tzend_hash_destroy(ht);
\t\t\tefree(ht);
\t\t} else if (node->ptr.leaf == leaf) {
\t\t\tZEND_HASH_FOREACH_NUM_KEY_PTR(ht, child_leaf, child_generator) {
\t\t\t\tnode->ptr.leaf = (zend_generator *) child_leaf;
\t\t\t\tbreak;
\t\t\t} ZEND_HASH_FOREACH_END();
\t\t}
\t} else if (node->ptr.leaf == leaf) {
\t\tZEND_ASSERT(replace_leaf != leaf);
\t\tnode->ptr.leaf = replace_leaf;
\t}
}
"""
new = """static void zend_generator_remove_leaf_child(zend_generator_node *node, zend_generator *leaf, zend_generator *replace_leaf) {
\tif (node->children > 1) {
\t\tHashTable *ht = node->child.ht;
\t\tzend_ulong child_leaf;
\t\tzend_generator *child_generator;
\t\tzend_generator *removed_child;

\t\tremoved_child = zend_hash_index_find_ptr(ht, (zend_ulong) leaf);
\t\tZEND_ASSERT(removed_child != NULL);
\t\tzend_hash_index_del(ht, (zend_ulong) leaf);
\t\tOBJ_RELEASE(&removed_child->std);

\t\tif (--node->children == 1) {
\t\t\tZEND_HASH_FOREACH_NUM_KEY_PTR(ht, child_leaf, child_generator) {
\t\t\t\tnode->child.single.leaf = (zend_generator *) child_leaf;
\t\t\t\tnode->child.single.child = child_generator;
\t\t\t\tif (node->ptr.leaf == leaf) {
\t\t\t\t\tnode->ptr.leaf = (zend_generator *) child_leaf;
\t\t\t\t}
\t\t\t\tbreak;
\t\t\t} ZEND_HASH_FOREACH_END();
\t\t\t/* We intentionally keep the reference for child_generator, which is now
\t\t\t * owned by node->child.single.child. */
\t\t\tzend_hash_destroy(ht);
\t\t\tefree(ht);
\t\t} else if (node->ptr.leaf == leaf) {
\t\t\tZEND_HASH_FOREACH_NUM_KEY_PTR(ht, child_leaf, child_generator) {
\t\t\t\tnode->ptr.leaf = (zend_generator *) child_leaf;
\t\t\t\tbreak;
\t\t\t} ZEND_HASH_FOREACH_END();
\t\t}
\t} else if (node->ptr.leaf == leaf) {
\t\tZEND_ASSERT(replace_leaf != leaf);
\t\tnode->ptr.leaf = replace_leaf;
\t}
}
"""
if old not in src:
    raise SystemExit('Pattern for zend_generator_remove_leaf_child not found')
src = src.replace(old, new)

# Patch parent_becomes_leaf block in zend_generator_dtor_storage to release single child ref
marker = "\t\t\t\tparent->node.ptr.root = toproot;\n\t\t\t\tparent->node.children = 0;\n"
if marker not in src:
    raise SystemExit('Marker for parent_becomes_leaf block not found')
src = src.replace(marker, "\t\t\t\tparent->node.ptr.root = toproot;\n\t\t\t\t/* parent stops being a yield-from node and becomes a leaf, drop the child reference */\n\t\t\t\tOBJ_RELEASE(&parent->node.child.single.child->std);\n\t\t\t\tparent->node.child.single.child = NULL;\n\t\t\t\tparent->node.children = 0;\n")

# Patch zend_generator_free_storage to release child references from yield-from tree
# Replace the existing block that only destroys ht.
old = """\tif (UNEXPECTED(generator->node.children > 1)) {
\t\tzend_hash_destroy(generator->node.child.ht);
\t\tefree(generator->node.child.ht);
\t}
"""
new = """\tif (UNEXPECTED(generator->node.children == 1)) {
\t\t/* Drop reference held by yield-from tree bookkeeping. */
\t\tif (generator->node.child.single.child) {
\t\t\tOBJ_RELEASE(&generator->node.child.single.child->std);
\t\t\tgenerator->node.child.single.child = NULL;
\t\t}
\t} else if (UNEXPECTED(generator->node.children > 1)) {
\t\tHashTable *ht = generator->node.child.ht;
\t\tzend_generator *child_generator;
\t\tZEND_HASH_FOREACH_PTR(ht, child_generator) {
\t\t\tOBJ_RELEASE(&child_generator->std);
\t\t} ZEND_HASH_FOREACH_END();
\t\tzend_hash_destroy(ht);
\t\tefree(ht);
\t}
"""
if old not in src:
    raise SystemExit('Pattern for ht destroy in zend_generator_free_storage not found')
src = src.replace(old, new)

path.write_text(src)
print('Patched', path)
